import type { MetadataRoute } from "next";
import { nobleNeighborhoods } from "../data/neighborhoods";
import { calculators } from "../data/calculators";
import { servicesExtended } from "../data/services-extended";

const siteUrl = "https://drjonybarbosa.com.br";

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();
  const staticRoutes = [
    "/",
    "/sobre",
    "/contato",
    "/especialidades",
    "/exames",
    "/servicos",
    "/calculadoras",
    "/localizacao",
  ];

  const specialtyRoutes = servicesExtended
    .filter((service) => service.category === "especialidade")
    .map((service) => `/especialidades/${service.slug}`);

  const examRoutes = servicesExtended
    .filter((service) => service.category === "exame")
    .map((service) => `/exames/${service.slug}`);

  const serviceRoutes = servicesExtended
    .filter((service) => service.category === "servico")
    .map((service) => `/servicos/${service.slug}`);

  const neighborhoodRoutes = nobleNeighborhoods.map(
    (neighborhood) => `/localizacao/${neighborhood.slug}`,
  );

  const calculatorRoutes = calculators.map(
    (calculator) => `/calculadoras/${calculator.slug}`,
  );

  return [
    ...staticRoutes,
    ...specialtyRoutes,
    ...examRoutes,
    ...serviceRoutes,
    ...calculatorRoutes,
    ...neighborhoodRoutes,
  ].map((route) => ({
    url: `${siteUrl}${route}`,
    lastModified: now,
    changeFrequency: route === "/" ? "weekly" : "monthly",
    priority: route === "/" ? 1 : 0.7,
  }));
}
